from sys import stdin
from math import log, ceil
T = int(stdin.readline())

def invf(n):
	if n == 0:
		return 0
	return sum((n // 5 ** i for i in range(1, int(log(n, 5)) + 1)))

def bsearch(inv, y):
	lb = 1
	ub = y * 5
	while ub - lb > 1:
		mid = (ub + lb) // 2
		if inv(mid) >= y:
			ub = mid
		elif inv(mid) < y:
			lb = mid
	if inv(lb) == y:
		return lb
	else:
		return ub
f = lambda x: bsearch(invf, x)
for _ in range(T):
	print(f(int(stdin.readline())))
